17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
107	        if (ownerAlreadyExists(owner) || emailAlreadyExists(owner)) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        if (dailyRegistrationLimitReached()) {
111	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
112	        }
113	        if (cityAtCapacity(owner.getCity())) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        if (owner.getRegistrationDate() == null) {
117	            owner.setRegistrationDate(LocalDate.now());
118	        }
119	        owner.setCity(resolveCity(owner.getCity()));
120	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
121	        owner.setMembershipNumber(membershipNumber);
122	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
123	        owner.setMembershipTier(membershipTierFor(membershipNumber));
124	        owner.setNamesakeCount(namesakeCount(owner.getLastName()));
125	        this.clinicService.saveOwner(owner);
126	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
127	        headers.setLocation(UriComponentsBuilder.newInstance()
128	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
129	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
130	    }
131	
132	    /**
133	     * The maximum number of owners that may be registered on any single day (by registration date).
134	     */
135	    private static final long MAX_OWNERS_PER_DAY = 20;
136	
137	    /**
138	     * Determines whether the maximum number of owners for the current day has already been reached.
139	     * Owners are counted by their registration date, so once {@value #MAX_OWNERS_PER_DAY} owners
140	     * carry today's registration date no further owners may be created today.
141	     *
142	     * @return {@code true} if today's registration limit has been reached
143	     */
144	    private boolean dailyRegistrationLimitReached() {
145	        LocalDate today = LocalDate.now();
146	        long registeredToday = this.clinicService.findAllOwners().stream()
147	            .filter(existing -> today.equals(existing.getRegistrationDate()))
148	            .count();
149	        return registeredToday >= MAX_OWNERS_PER_DAY;
150	    }
151	
152	    /**
153	     * The maximum number of owners that may be registered in any single city.
154	     */
155	    private static final long MAX_OWNERS_PER_CITY = 8;
156	
157	    /**
158	     * Determines whether the given city has already reached its capacity of
159	     * {@value #MAX_OWNERS_PER_CITY} owners. Owners are counted per city ignoring letter case, so
160	     * once a city holds {@value #MAX_OWNERS_PER_CITY} owners no further owners may be created there.
161	     *
162	     * @param city the raw city supplied for the owner being created, may be {@code null}
163	     * @return {@code true} if the city already contains the maximum number of owners
164	     */
165	    private boolean cityAtCapacity(String city) {
166	        if (city == null) {
167	            return false;
168	        }
169	        long ownersInCity = this.clinicService.findAllOwners().stream()
170	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
171	            .count();
172	        return ownersInCity >= MAX_OWNERS_PER_CITY;
173	    }
174	
175	    /**
176	     * Resolves the city to store for a newly created owner. If another owner is already stored in
177	     * the same city (compared ignoring letter case), that existing owner's exact spelling of the
178	     * city name is reused so that a single city is always represented consistently. Otherwise the
179	     * supplied city is title-cased (see {@link #titleCase(String)}) before being stored.
180	     *
181	     * @param city the raw city supplied for the owner being created, may be {@code null}
182	     * @return the city to store, or {@code null} if {@code city} is {@code null}
183	     */
184	    private String resolveCity(String city) {
185	        if (city == null) {
186	            return null;
187	        }
188	        return this.clinicService.findAllOwners().stream()
189	            .map(Owner::getCity)
190	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
191	            .findFirst()
192	            .orElseGet(() -> titleCase(city));
193	    }
194	
195	    /**
196	     * Title-cases a value so that the first letter of every whitespace-separated word is
197	     * upper-cased and every other letter is lower-cased, preserving the original whitespace. For
198	     * example {@code "new  york"} becomes {@code "New  York"} and {@code "LONDON"} becomes
199	     * {@code "London"}.
200	     *
201	     * @param value the raw value, may be {@code null}
202	     * @return the title-cased value, or {@code null} if {@code value} is {@code null}
203	     */
204	    private static String titleCase(String value) {
205	        if (value == null) {
206	            return null;
207	        }
208	        StringBuilder result = new StringBuilder(value.length());
209	        boolean startOfWord = true;
210	        for (int i = 0; i < value.length(); i++) {
211	            char c = value.charAt(i);
212	            if (Character.isWhitespace(c)) {
213	                startOfWord = true;
214	                result.append(c);
215	            } else {
216	                result.append(startOfWord ? Character.toUpperCase(c) : Character.toLowerCase(c));
217	                startOfWord = false;
218	            }
219	        }
220	        return result.toString();
221	    }
222	
223	    /**
224	     * Builds the customer code for a newly created owner in the given city, formatted as
225	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number of owners
226	     * already stored in that city, zero-padded to four digits (e.g. {@code LONDON-0007}). The
227	     * count of existing owners in the city ignores letter case.
228	     *
229	     * @param city the city of the owner being created
230	     * @return the assigned customer code
231	     */
232	    private String nextCustomerCode(String city) {
233	        long ownersInCity = this.clinicService.findAllOwners().stream()
234	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
235	            .count();
236	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
237	    }
238	
239	    /**
240	     * The maximum membership number that still qualifies an owner for the founding tier. The
241	     * first {@value #MAX_FOUNDING_MEMBERS} owners ever created are founding members.
242	     */
243	    private static final int MAX_FOUNDING_MEMBERS = 100;
244	
245	    /**
246	     * Resolves the membership tier for a newly created owner from its sequential membership
247	     * number. The first {@value #MAX_FOUNDING_MEMBERS} owners ever created are {@code FOUNDING};
248	     * every later owner is {@code STANDARD}.
249	     *
250	     * @param membershipNumber the owner's sequential membership number
251	     * @return {@code "FOUNDING"} or {@code "STANDARD"}
252	     */
253	    private static String membershipTierFor(int membershipNumber) {
254	        return membershipNumber <= MAX_FOUNDING_MEMBERS ? "FOUNDING" : "STANDARD";
255	    }
256	
257	    /**
258	     * Counts how many existing owners already share the given last name, ignoring letter case and
259	     * surrounding or repeated whitespace. This is evaluated at the moment a new owner is created,
260	     * before that owner is stored, so it reflects the number of other owners that carry the same
261	     * last name.
262	     *
263	     * @param lastName the last name of the owner being created, may be {@code null}
264	     * @return the number of other owners already sharing that last name
265	     */
266	    private int namesakeCount(String lastName) {
267	        String normalized = normalize(lastName);
268	        return (int) this.clinicService.findAllOwners().stream()
269	            .filter(existing -> Objects.equals(normalize(existing.getLastName()), normalized))
270	            .count();
271	    }
272	
273	    /**
274	     * Determines whether an owner already exists using the same telephone number.
275	     * Comparison ignores letter case and surrounding or repeated whitespace.
276	     *
277	     * @param owner the candidate owner to check
278	     * @return {@code true} if any other owner with the same telephone is already stored
279	     */
280	    private boolean ownerAlreadyExists(Owner owner) {
281	        String telephone = normalizeTelephone(owner.getTelephone());
282	        return this.clinicService.findAllOwners().stream()
283	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
284	    }
285	
286	    /**
287	     * Normalizes a telephone number to digits only, stripping spaces, dashes and
288	     * parentheses (any non-digit character). This is the canonical stored form and is
289	     * used for the telephone-uniqueness check, so {@code "(613) 555-0100"} and
290	     * {@code "6135550100"} are treated as the same number.
291	     *
292	     * @param telephone the raw telephone value, may be {@code null}
293	     * @return the digits-only value, or {@code null} if {@code telephone} is {@code null}
294	     */
295	    private static String normalizeTelephone(String telephone) {
296	        if (telephone == null) {
297	            return null;
298	        }
299	        return telephone.replaceAll("[^0-9]", "");
300	    }
301	
302	    /**
303	     * Determines whether another owner already uses the same email address.
304	     * Owners without an email are ignored, so a missing email never conflicts.
305	     * Comparison ignores letter case and surrounding or repeated whitespace.
306	     *
307	     * @param owner the candidate owner to check
308	     * @return {@code true} if the candidate supplies an email already used by a stored owner
309	     */
310	    private boolean emailAlreadyExists(Owner owner) {
311	        String email = normalize(owner.getEmail());
312	        if (email == null || email.isEmpty()) {
313	            return false;
314	        }
315	        return this.clinicService.findAllOwners().stream()
316	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
317	    }
318	
319	    /**
320	     * Normalizes a value for duplicate detection so that comparisons ignore letter
321	     * case and surrounding or repeated whitespace. Leading and trailing whitespace is
322	     * trimmed, any run of internal whitespace is collapsed to a single space, and the
323	     * result is lower-cased. For example {@code "  john   smith "} and {@code "John Smith"}
324	     * both normalize to {@code "john smith"}.
325	     *
326	     * @param value the raw value, may be {@code null}
327	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
328	     */
329	    private static String normalize(String value) {
330	        if (value == null) {
331	            return null;
332	        }
333	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
334	    }
335	
336	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
337	    @Override
338	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
339	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
340	        if (currentOwner == null) {
341	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
342	        }
343	        currentOwner.setAddress(ownerFieldsDto.getAddress());
344	        currentOwner.setCity(ownerFieldsDto.getCity());
345	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
346	        currentOwner.setLastName(ownerFieldsDto.getLastName());
347	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
348	        this.clinicService.saveOwner(currentOwner);
349	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
350	    }
351	
352	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
353	    @Transactional
354	    @Override
355	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
356	        Owner owner = this.clinicService.findOwnerById(ownerId);
357	        if (owner == null) {
358	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
359	        }
360	        this.clinicService.deleteOwner(owner);
361	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
362	    }
363	
364	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
365	    @Override
366	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
367	        Owner owner = this.clinicService.findOwnerById(ownerId);
368	        if (owner == null) {
369	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
370	        }
371	        HttpHeaders headers = new HttpHeaders();
372	        Pet pet = petMapper.toPet(petFieldsDto);
373	        owner.setId(ownerId);
374	        pet.setOwner(owner);
375	        pet.getType().setName(null);
376	        this.clinicService.savePet(pet);
377	        PetDto petDto = petMapper.toPetDto(pet);
378	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
379	            .buildAndExpand(pet.getId()).toUri());
380	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
381	    }
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Override
385	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
386	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
387	        if (currentOwner != null) {
388	            Pet currentPet = this.clinicService.findPetById(petId);
389	            if (currentPet != null) {
390	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
391	                currentPet.setName(petFieldsDto.getName());
392	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
393	                this.clinicService.savePet(currentPet);
394	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
395	            }
396	        }
397	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
398	    }
399	
400	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
401	    @Override
402	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
403	        HttpHeaders headers = new HttpHeaders();
404	        Visit visit = visitMapper.toVisit(visitFieldsDto);
405	        Pet pet = new Pet();
406	        pet.setId(petId);
407	        visit.setPet(pet);
408	        this.clinicService.saveVisit(visit);
409	        VisitDto visitDto = visitMapper.toVisitDto(visit);
410	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
411	            .buildAndExpand(visit.getId()).toUri());
412	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
413	    }
414	
415	
416	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
417	    @Override
418	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
419	        Owner owner = this.clinicService.findOwnerById(ownerId);
420	        if (owner != null) {
421	            Pet pet = owner.getPet(petId);
422	            if (pet != null) {
423	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
424	            }
425	        }
426	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
427	    }
428	}
